// Inlines drizzle-kit's SQL migrations into a TypeScript module that drizzle's expo-sqlite
// migrator can read directly (no babel .sql import plugin needed). Run via `npm run db:generate`.
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const outDir = path.join(root, 'drizzle');
const journal = JSON.parse(fs.readFileSync(path.join(outDir, 'meta', '_journal.json'), 'utf8'));

const migrations = {};
for (const entry of journal.entries) {
  const key = `m${String(entry.idx).padStart(4, '0')}`;
  migrations[key] = fs.readFileSync(path.join(outDir, `${entry.tag}.sql`), 'utf8');
}

const source = `// Generated by scripts/bundle-migrations.js from ./drizzle. Do not edit by hand.
// To change the database, edit src/db/schema.ts and run \`npm run db:generate\`.
const migrations = ${JSON.stringify({ journal: { entries: journal.entries }, migrations }, null, 2)};

export default migrations;
`;

fs.writeFileSync(path.join(root, 'src', 'db', 'migrations.ts'), source);
console.log(`Bundled ${journal.entries.length} migration(s) into src/db/migrations.ts`);
